+	ask: (deadline: AbortSignal) => Promise<Completion | null>,
+	kinds: readonly SuggestionKind[],
+	timeoutMs: number,
+	stale: AbortSignal | undefined,
+	armed: Promise<void>,
+): Promise<PoolOutcome> {
